import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import Page from '../../components/Page.jsx';
import Title from '../../components/Title.jsx';
import Navi from '../../components/Navi.jsx';
import naviDB from '../../json/navi.json';
import Detail from '../../components/Detail';
import * as MyLayout from '../../lib/MyLayout.jsx';
import API_BASE from '../../utils/apiConfig';
import useLoginStatus from '../../utils/useLoginStatus';

const EducationDetails = () => {
  const params = useParams();
  const [info, setInfo] = useState('');
  const [expire, setExpire] = useState('');
  const [administration, setAdministration] = useState('');
  const [address, setAddress] = useState('');
  const [etct, setEtct] = useState('');
  const { startLoading, finishLoading } = MyLayout.useLoading();
  const { openDialog } = MyLayout.useDialog();
  const { values } = params;
  const { upDateLogin, dataContent } = useLoginStatus();

  const loadDetail = async () => {
    startLoading('정책 정보 불러오는 중...');
    try {
      const res = await axios.get(`${API_BASE}/educationApi`);
      const rawData = res.data.youthPolicyList;
      if (!rawData) return;

      const list = Array.isArray(rawData) ? rawData : [rawData];
      const found = list.find((item) => item.plcyNm === values);

      if (found) {
        setInfo(found.plcyExplnCn || '내용 없음');
        setExpire(found.bizPrdEndYmd || '기간 정보 없음');
        setAdministration(found.sprvsnInstCdNm || '');
        setAddress(found.aplyUrlAddr || found.refUrlAddr1 || '');
        setEtct(found.plcySprtCn || '없음');
      }
    } catch (err) {
      console.log('EducationDetail 로드 오류:', err.message || err);
    } finally {
      finishLoading();
    }
  };

  const handleWishlist = async (e) => {
    const letter = e;
    if (!upDateLogin) {
      return alert('로그인 이후 이용가능합니다');
    }
    try {
      const link = `/details/education/${values}`;
      const res = await axios.post(`${API_BASE}/MyList`, [dataContent[0], '없음', link, values]);
      if (res.data === 'already') {
        return alert('이미 찜한 항목입니다');
      }
      letter.style.color = '#f00000';
      return alert('찜에 성공했습니다.');
    } catch (err) {
      openDialog(null);
      return alert('오류가 발생했습니다');
    }
  };

  useEffect(() => {
    loadDetail();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [values]);

  return (
    <Page
      header={<Title title={'교육 정책 상세'} />}
      footer={<Navi data={upDateLogin ? naviDB.Info : naviDB.detail} />}
    >
      <Detail
        title={values}
        info={info}
        expire={expire}
        administration={administration}
        etct={etct}
        address={address}
        onClick={(e) => handleWishlist(e.target)}
      />
    </Page>
  );
};

export default EducationDetails;
