import React, { useState, useEffect } from 'react';

const FinDetail = ({ title, data, moreData, onClick }) => {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (data && data.length > 0) {
      setOpen(true);
    } else {
      setOpen(false);
    }
  }, [data]);

  const item = data && data[0];

  return (
    <div className="detail">
      <h3>{title}</h3>
      {open && item ? (
        <>
          <ul className="detail_cont">
            <li>
              <strong>상품명</strong>
              <p>{item.prdtnm || '-'}</p>
            </li>
            <li>
              <strong>가입대상</strong>
              <p>{item.member || '-'}</p>
            </li>
            <li>
              <strong>가입제한</strong>
              <p>{item.deny || '-'}</p>
            </li>
            <li>
              <strong>우대조건</strong>
              <p>{item.spcl || '-'}</p>
            </li>
            <li>
              <strong>기타사항</strong>
              <p>{item.etct || '-'}</p>
            </li>
            <li>
              <strong>이자율 / 연체금리</strong>
              <p>{item.mtrt || '-'}</p>
            </li>
            {moreData && (
              <>
                <li>
                  <strong>중도상환수수료</strong>
                  <p>{item.erlyfee || '-'}</p>
                </li>
                <li>
                  <strong>대출한도</strong>
                  <p>{item.loanlmt || '-'}</p>
                </li>
              </>
            )}
          </ul>
          <ul>
            <li>
              <strong>주관은행</strong>
              {item.banknm || '-'}
            </li>
            <li>
              <strong>공시시작일</strong>
              {item.start || '-'}
            </li>
            <li>
              <strong>공시만기일</strong>
              {item.expire || '-'}
            </li>
            <li onClick={onClick} style={{ cursor: 'pointer' }}>
              ♡ 찜하기
            </li>
          </ul>
        </>
      ) : (
        <div style={{ textAlign: 'center', padding: '50px', color: '#878787' }}>
          상품 정보를 불러올 수 없습니다.
        </div>
      )}
    </div>
  );
};

export default FinDetail;
