import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import Page from '../../components/Page';
import Title from '../../components/Title';
import Navi from '../../components/Navi';
import naviDB from '../../json/navi.json';
import Formcontrol from '../../components/Formcontrol.jsx';
import * as MyForm from '../../lib/MyForm.jsx';
import * as MyLayout from '../../lib/MyLayout.jsx';
import API_BASE from '../../utils/apiConfig';

const Login = () => {
  const [login, setLogin] = useState(false);
  const navigate = useNavigate();
  const { startLoading, finishLoading } = MyLayout.useLoading();

  const validate = (values) => {
    const errors = {};
    const idRegExp = /^[a-z]+[a-z0-9]{5,19}$/g;
    const passwordRegExp = /^(?=.*\d)(?=.*[a-zA-Z])[0-9a-zA-Z]{8,16}$/;
    if (!values.login_id || !idRegExp.test(values.login_id)) {
      errors.login_id = '아이디를 올바르게 입력해주세요 (영문 소문자+숫자 6~20자)';
    }
    if (!values.login_password || !passwordRegExp.test(values.login_password)) {
      errors.login_password = '비밀번호를 올바르게 입력해주세요 (영문+숫자 8~16자)';
    }
    return errors;
  };

  const onClick = async (e) => {
    if (!login) return;

    const idRegExp = /^[a-z]+[a-z0-9]{5,19}$/g;
    const passwordRegExp = /^(?=.*\d)(?=.*[a-zA-Z])[0-9a-zA-Z]{8,16}$/;
    const form = e.closest('.join')?.querySelector('#login_form');
    if (!form) return;

    const value_id = form.login_id?.value;
    const value_password = form.login_password?.value;

    if (!idRegExp.test(value_id) || !passwordRegExp.test(value_password)) {
      return alert('아이디와 비밀번호를 다시 확인해주세요');
    }

    try {
      startLoading('로그인 시도중...');
      const res = await axios.post(`${API_BASE}/login`, [value_id, value_password]);
      const data = res.data;

      const users = Array.isArray(data) ? data : [data];
      const matched = users.find(
        (u) => u.userId === value_id && u.userPassword === value_password
      );

      if (matched) {
        finishLoading();
        navigate('/');
      } else {
        finishLoading();
        alert('아이디 또는 비밀번호가 일치하지 않습니다');
      }
    } catch (err) {
      finishLoading();
      console.log('로그인 오류:', err.message || err);
      alert('서버 연결에 실패했습니다. 백엔드 서버가 실행 중인지 확인하세요.');
    }
  };

  useEffect(() => {
    setLogin(true);
  }, []);

  return (
    <Page header={<Title title={'로그인'} />} footer={<Navi data={naviDB.join} />}>
      {login && (
        <div className="join login">
          <div className="joinBox">
            <h3>아이디 및 비밀번호를 입력해주세요</h3>
            <MyForm.Form
              id="login_form"
              className="LoginForm"
              initialValue={{ login_id: '', login_password: '' }}
              validate={validate}
            >
              <Formcontrol
                label={'아이디'}
                htmlFor="login_id"
                required
                error={<MyForm.ErrorMessage name="login_id" />}
              >
                <MyForm.FormField
                  type="text"
                  placeholder="아이디를 입력해주세요"
                  name="login_id"
                />
              </Formcontrol>
              <Formcontrol
                label={'비밀번호'}
                required
                htmlFor="login_password"
                error={<MyForm.ErrorMessage name="login_password" />}
              >
                <MyForm.FormField
                  type="password"
                  placeholder="비밀번호를 입력해주세요"
                  name="login_password"
                />
              </Formcontrol>
            </MyForm.Form>
            <button className="submitBtn" onClick={(e) => onClick(e.target)}>
              로그인
            </button>
          </div>
        </div>
      )}
    </Page>
  );
};

export default Login;
