import React from 'react';

const Detail = ({ title, info, administration, expire, address, etct, onClick }) => {
  const hasAddress = address && address.trim().length > 0;

  return (
    <div className="detail">
      <h3>{title || '정보를 불러오는 중...'}</h3>
      <ul className="detail_cont">
        <li>
          <strong>정책소개</strong>
          <p>{info || '-'}</p>
        </li>
        <li>
          <strong>지원내용</strong>
          <p>{etct || '-'}</p>
        </li>
        <li>
          <strong>신청 사이트</strong>
          <p>
            {hasAddress ? (
              <a href={address} target="_blank" rel="noopener noreferrer" style={{ color: '#174283', wordBreak: 'break-all' }}>
                {address}
              </a>
            ) : (
              '신청 링크 없음'
            )}
          </p>
        </li>
      </ul>
      <ul>
        <li>
          <strong>주관</strong>
          {administration || '-'}
        </li>
        <li>
          <strong>기간</strong>
          {expire || '-'}
        </li>
        <li onClick={onClick} style={{ cursor: 'pointer' }}>
          ♡ 찜하기
        </li>
      </ul>
    </div>
  );
};

export default Detail;
