import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Page from '../../components/Page';
import Title from '../../components/Title';
import Navi from '../../components/Navi';
import Info from '../../components/Info';
import NaviDB from '../../json/navi.json';
import * as MyLayout from '../../lib/MyLayout';
import API_BASE from '../../utils/apiConfig';
import useLoginStatus from '../../utils/useLoginStatus';

const Residence = () => {
  const [data, setData] = useState(false);
  const [content, setContent] = useState(false);
  const [href, setHref] = useState('');
  const { startLoading, finishLoading } = MyLayout.useLoading();
  const { upDateLogin, logout } = useLoginStatus();

  const loadData = async () => {
    startLoading('주거 정책 불러오는 중...');
    try {
      const res = await axios.get(`${API_BASE}/residenceApi`);
      const res_data = res.data.youthPolicyList;

      if (!res_data) {
        setData([]);
        setContent(['데이터를 불러올 수 없습니다']);
        setHref('');
        return;
      }

      const list = Array.isArray(res_data) ? res_data : [res_data];
      // residenceApi는 이미 bscPlanPlcyWayNo=002 필터가 서버에서 적용됨
      const titles = list.map((item) => [item.plcyNm]);
      const contents = list.map((item) => [item.plcySprtCn]);

      setData(titles);
      setContent(contents);
      setHref('/details/residence');
    } catch (err) {
      console.log('residence 데이터 로드 오류:', err.message || err);
      setData([]);
      setContent(['검색결과가 없습니다']);
      setHref('');
    } finally {
      finishLoading();
    }
  };

  const handleLogout = async () => {
    await logout(startLoading, finishLoading);
  };

  useEffect(() => {
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <Page
      header={<Title title={'주거'} backURL={'/'} />}
      footer={
        upDateLogin ? (
          <Navi loginUpload color onClick={handleLogout} />
        ) : (
          <Navi data={NaviDB.Info} />
        )
      }
    >
      <Info
        id={'주거'}
        list01={data}
        list02={content}
        name={href}
      />
    </Page>
  );
};

export default Residence;
