import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const FinanceInfo = ({ id, onChange, data, dataName, name, selectedType }) => {
  const [listup, setListup] = useState(false);
  const navigate = useNavigate();

  const handleItemClick = (productName) => {
    if (name) {
      navigate(`${name}/${encodeURIComponent(productName)}`);
    }
  };

  useEffect(() => {
    if (!dataName || dataName === '검색결과가 없습니다') {
      setListup(false);
    } else if (Array.isArray(dataName) && dataName.length > 0) {
      setListup(true);
    } else {
      setListup(false);
    }
  }, [dataName]);


  return (
    <div className="financeInfo">
      <div className="formBox">
        <form id="myForm">
          <select form="myForm" id={id} onChange={onChange} name={id} value={selectedType || ''}>
            {data.map((v, i) => (
              <option key={id + i} value={v.name}>
                {v.name}
              </option>
            ))}
          </select>
        </form>
      </div>
      <div className="list">
        <div className="listBox">
          <ul>
            <li className="list_title">
              <p>금융상품 목록</p>
            </li>
            {listup && Array.isArray(dataName) ? (
              dataName.map((v, i) => (
                <li key={'list' + i}>
                  <span>
                    {v.title}
                    <p
                      onClick={() => handleItemClick(v.prdtnm)}
                      style={{ cursor: 'pointer' }}
                    >
                      {v.prdtnm}
                    </p>
                    <p className="finDate" style={{ color: '#000' }}>
                      {v.typenm}
                    </p>
                    <p className="finDate">{v.start}</p>
                  </span>
                </li>
              ))
            ) : (
              <li style={{ textAlign: 'center', padding: '20px', color: '#878787' }}>
                {typeof dataName === 'string' ? dataName : '금융상품을 선택해주세요'}
              </li>
            )}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default FinanceInfo;
