import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import Page from '../../components/Page.jsx';
import Title from '../../components/Title.jsx';
import Navi from '../../components/Navi.jsx';
import naviDB from '../../json/navi.json';
import FinDetail from './FinDetail.jsx';
import * as MyLayout from '../../lib/MyLayout.jsx';
import API_BASE from '../../utils/apiConfig';
import useLoginStatus from '../../utils/useLoginStatus';

const FinanceDetails = () => {
  const params = useParams();
  const [data, setData] = useState(null);
  const [moreData, setMoreData] = useState(false);
  const { startLoading, finishLoading } = MyLayout.useLoading();
  const { openDialog } = MyLayout.useDialog();
  const { values, name } = params;
  const { upDateLogin, dataContent } = useLoginStatus();

  const loadDetail = async () => {
    startLoading('금융 상품 정보 불러오는 중...');
    try {
      const res = await axios.post(`${API_BASE}/financeApi`, { [name]: name });
      const res_data = res.data.baseList;

      if (!res_data || res_data.length === 0) {
        finishLoading();
        return;
      }

      const list = Array.isArray(res_data) ? res_data : [res_data];
      const found = list.find((item) => item.fin_prdt_nm === values);

      if (!found) {
        finishLoading();
        return;
      }

      // join_deny 코드 → 한글 변환
      let joinDeny = found.join_deny;
      if (joinDeny === 1 || joinDeny === "1") joinDeny = '제한없음';
      else if (joinDeny === 2 || joinDeny === "2") joinDeny = '서민전용';
      else if (joinDeny === 3 || joinDeny === "3") joinDeny = '일부제한';

      let detail = {};

      if (name === '전세자금대출' || name === '주택담보대출') {
        detail = {
          prdtnm: found.fin_prdt_nm,
          etct: found.loan_inci_expn,
          member: found.join_way || '없음',
          deny: joinDeny || '없음',
          mtrt: found.dly_rate,
          banknm: found.kor_co_nm,
          start: found.dcls_strt_day,
          expire: found.dcls_end_day,
          erlyfee: found.erly_rpay_fee,
          loanlmt: found.loan_lmt,
          spcl: found.spcl_cnd,
        };
        setMoreData(true);
      } else if (name === '개인신용대출') {
        detail = {
          prdtnm: found.fin_prdt_nm,
          etct: `CB회사명: ${found.cb_name}`,
          member: found.join_way || '없음',
          deny: joinDeny || '없음',
          mtrt: found.dly_rate,
          banknm: found.kor_co_nm,
          start: found.dcls_strt_day,
          expire: found.dcls_end_day,
          erlyfee: found.erly_rpay_fee,
          loanlmt: found.loan_lmt,
          spcl: found.spcl_cnd,
        };
        setMoreData(false);
      } else if (name === '연금저축') {
        detail = {
          prdtnm: found.fin_prdt_nm,
          etct: `연금종류: ${found.pnsn_kind_nm} / 상품유형: ${found.prdt_type_nm}`,
          member: found.join_way || '없음',
          deny: joinDeny || '없음',
          mtrt: found.dly_rate,
          banknm: found.kor_co_nm,
          start: found.dcls_strt_day,
          expire: found.dcls_end_day,
          erlyfee: found.erly_rpay_fee,
          loanlmt: found.loan_lmt,
          spcl: `판매사: ${found.sale_co}`,
        };
        setMoreData(false);
      } else {
        // 정기예금, 적금
        detail = {
          prdtnm: found.fin_prdt_nm,
          etct: found.etc_note,
          member: found.join_member,
          deny: joinDeny,
          mtrt: found.mtrt_int,
          banknm: found.kor_co_nm,
          start: found.dcls_strt_day,
          expire: found.dcls_end_day,
          spcl: found.spcl_cnd,
        };
        setMoreData(false);
      }

      setData([detail]);
    } catch (err) {
      console.log('FinanceDetail 로드 오류:', err.message || err);
      openDialog(null);
    } finally {
      finishLoading();
    }
  };

  const handleWishlist = async (e) => {
    const letter = e;
    if (!upDateLogin) {
      return alert('로그인 이후 이용가능합니다');
    }
    try {
      const link = `/details/finance/${name}/${values}`;
      const res = await axios.post(`${API_BASE}/MyList`, [dataContent[0], name, link, values]);
      if (res.data === 'already') {
        return alert('이미 찜한 상품입니다');
      }
      letter.style.color = '#f00000';
      return alert('찜에 성공했습니다.');
    } catch (err) {
      openDialog(null);
      return alert('오류가 발생했습니다');
    }
  };

  useEffect(() => {
    loadDetail();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [values, name]);

  return (
    <Page
      header={<Title title={'금융 상품 상세'} />}
      footer={<Navi data={upDateLogin ? naviDB.Info : naviDB.detail} />}
    >
      <FinDetail
        data={data}
        title={values}
        moreData={moreData}
        onClick={(e) => handleWishlist(e.target)}
      />
    </Page>
  );
};

export default FinanceDetails;
