import React from 'react';
import { useNavigate } from 'react-router-dom';

const Info = ({ id, name, list01, list02 }) => {
  const navigate = useNavigate();
  const hasData = Array.isArray(list01) && list01.length > 0;

  const onClick = (title) => {
    if (name && title) {
      navigate(`${name}/${encodeURIComponent(title)}`);
    }
  };

  return (
    <div className="info">
      <div className="list">
        <div className="listBox">
          <ul>
            <li className="list_title">
              <p>{id} 정책</p>
            </li>
            {hasData ? (
              list01.map((titleArr, i) => {
                const title = Array.isArray(titleArr) ? titleArr[0] : titleArr;
                const desc = list02 && list02[i]
                  ? (Array.isArray(list02[i]) ? list02[i][0] : list02[i])
                  : '';
                return (
                  <li key={'list' + i}>
                    <span onClick={() => onClick(title)} style={{ cursor: 'pointer' }}>
                      {title}
                    </span>
                    <p>{desc}</p>
                  </li>
                );
              })
            ) : (
              <li style={{ textAlign: 'center', padding: '30px', color: '#878787' }}>
                {list02 && list02[0] === '검색결과가 없습니다'
                  ? '검색결과가 없습니다'
                  : list01 === false
                  ? '정책 정보를 불러오는 중...'
                  : '해당 카테고리의 정책이 없습니다'}
              </li>
            )}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default Info;
