import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import Page from '../components/Page.jsx';
import Title from '../components/Title.jsx';
import Navi from '../components/Navi.jsx';
import NaviDB from '../json/navi.json';
import API_BASE from '../utils/apiConfig';
import useLoginStatus from '../utils/useLoginStatus';

const MyList = () => {
  const [myListup, setMyListup] = useState([]);
  const { upDateLogin, dataContent, logout } = useLoginStatus();

  const loadMyList = async () => {
    if (!upDateLogin || !dataContent) return;
    try {
      const res = await axios.get(`${API_BASE}/MyList`);
      const data = res.data;
      if (Array.isArray(data) && data.length > 0) {
        // 현재 로그인된 유저의 찜 목록만 필터
        const myItems = data
          .filter((item) => item.userId === dataContent[0])
          .map((item) => ({
            title: item.title,
            link: item.link,
            administration: item.section,
          }));
        setMyListup(myItems);
      }
    } catch (err) {
      console.log('MyList 로드 오류:', err.message || err);
    }
  };

  const handleLogout = async () => {
    await logout();
  };

  useEffect(() => {
    if (upDateLogin) {
      loadMyList();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [upDateLogin]);

  if (upDateLogin) {
    return (
      <Page
        header={<Title title={'찜목록'} />}
        footer={<Navi Mylist color onClick={handleLogout} />}
      >
        <div className="Mylist">
          <ul>
            <h3>{dataContent && dataContent[0]}님의 찜목록</h3>
            {myListup.length > 0 ? (
              myListup.map((v, i) => (
                <li key={'myList' + i}>
                  <Link to={v.link}>
                    <span>{v.title}</span>
                    <p>{v.administration}</p>
                  </Link>
                </li>
              ))
            ) : (
              <li style={{ textAlign: 'center', padding: '20px', color: '#878787' }}>
                찜한 항목이 없습니다
              </li>
            )}
          </ul>
        </div>
      </Page>
    );
  }

  return (
    <Page
      header={<Title title={'찜목록'} />}
      footer={<Navi data={NaviDB.home} />}
    >
      <div className="Mylist">
        <ul>
          <h3>로그인 후 이용 가능합니다</h3>
          <li style={{ textAlign: 'center', paddingTop: '20px' }}>
            <Link to="/login" style={{ color: '#174283' }}>로그인 하러 가기</Link>
          </li>
        </ul>
      </div>
    </Page>
  );
};

export default MyList;
